		logs, err := signoz.NewBatchingLogClient(exp, signoz.LogClientOptions{Resource: resource, Batch: signoz.BatchOptions{
			OnDrop: func(r []signoz.LogRecord, _ signoz.DropReason) { onDropped(r) },
		}})
		if err != nil {
			return nil, err
		}
		return &signoz.LogConnection{Logs: logs, Close: func(ctx context.Context) error {
			*closed++
			return logs.Close(ctx)
		}}, nil
