func TestRequestMiddleware(t *testing.T) {
	prev := slog.Default()
	t.Cleanup(func() { slog.SetDefault(prev) })
	buf := &syncBuffer{}
	if _, shutdown, err := signoz.InitLogging(context.Background(), signoz.InitOptions{Env: map[string]string{}, Writer: buf}); err != nil {
		t.Fatal(err)
	} else {
		defer func() { _ = shutdown(context.Background()) }()
	}
	var seen string
	h := signoz.RequestMiddleware(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		seen = signoz.RequestIDFrom(r.Context())
		switch r.URL.Path {
		case "/missing":
			w.WriteHeader(http.StatusNotFound)
			w.WriteHeader(http.StatusTeapot)
		case "/fail":
			w.WriteHeader(http.StatusServiceUnavailable)
		case "/write":
			_, _ = w.Write([]byte("ok"))
		}
	}))
	for _, c := range []struct {
		path, id, level string
		status          float64
	}{{"/write", "abc", "info", 200}, {"/missing", "", "warn", 404}, {"/fail", strings.Repeat("x", 200), "error", 503}, {"/empty", "", "info", 200}} {
		req := httptest.NewRequest(http.MethodGet, c.path, nil)
		if c.id != "" {
			req.Header.Set(signoz.RequestIDHeader, c.id)
		}
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, req)
		got := rec.Header().Get(signoz.RequestIDHeader)
		if got != seen || got == "" || (c.id == "abc" && got != "abc") || len(got) > 128 {
			t.Fatalf("request id %q seen %q", got, seen)
		}
		l := buf.lines(t)
		last := l[len(l)-1]
		if last["msg"] != "request completed" || last["level"] != c.level || last["http.status_code"] != c.status || last["request_id"] != got {
			t.Fatalf("line %v", last)
		}
	}
	n := len(buf.lines(t))
	h.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest(http.MethodGet, "/health/live", nil))
	if len(buf.lines(t)) != n {
		t.Fatal("health probe logged")
	}
}
